//! Window icon: the same raster as the executable icon (branding/icons, generated by
//! infra/branding/make-icons.py), so the title bar, taskbar and Explorer agree.

const APP_PNG: &[u8] = include_bytes!("../../../branding/icons/app-256.png");

/// The app icon as RGBA for the window (256×256).
pub fn app_icon() -> egui::IconData {
    let img = image::load_from_memory_with_format(APP_PNG, image::ImageFormat::Png)
        .expect("embedded app icon")
        .into_rgba8();
    let (width, height) = img.dimensions();
    egui::IconData {
        rgba: img.into_raw(),
        width,
        height,
    }
}
